/* 项目协作台 2.0：原生静态应用，渲染与业务计算共用 BoardCore。 */
(function(){
'use strict';
const C=window.BoardCore;
const KEYS=window.BoardStorage.KEYS;
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',folder:'<path d="M3 7a2 2 0 0 1 2-2h5l2 2h7a2 2 0 0 1 2 2v10H3Z"/>',check:'<path d="m5 12 4 4L19 6"/>',list:'<path d="M9 5h12M9 12h12M9 19h12M3 5h.01M3 12h.01M3 19h.01"/>',flag:'<path d="M4 21V4c5-5 10 5 16 0v11c-6 5-11-5-16 0"/>',warning:'<path d="m12 3 10 18H2L12 3Z M12 9v4m0 4h.01"/>',chart:'<path d="M4 20V10M10 20V4M16 20v-8M22 20H2"/>',settings:'<path d="M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1Z"/>',database:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 11h18M7 15h3"/>',play:'<path d="m8 4 13 8-13 8V4Z"/>',ring:'<path d="M20 12a8 8 0 1 1-8-8M12 4a8 8 0 0 1 8 8"/>',people:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M22 21v-2a4 4 0 0 0-3-4M16 3a4 4 0 0 1 0 8"/><circle cx="9" cy="7" r="4"/>',book:'<path d="M12 5v16M3 3c4 0 7 1 9 3 2-2 5-3 9-3v16c-4 0-7 0-9 2-2-2-5-2-9-2V3Z"/>',megaphone:'<path d="M3 10v5h5l13 5V4L8 10H3ZM8 15l3 7h4l-3-6"/>',kanban:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M8 7v7M12 7v10M16 7v4"/>',timeline:'<path d="M3 5h8v4H3ZM8 11h10v4H8ZM14 17h7v4h-7Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.folder}</svg>`;
const nav=[['overview','项目总览','grid','每一步推进，都清晰可见。'],['projects','项目管理','folder','从业务目标到阶段交付，掌握项目全貌。'],['tasks','任务管理','list','拆解工作，有序协同，让任务真正落地。'],['progress','进度与里程碑','flag','沿着时间轴，追踪每一个关键节点。'],['risks','风险与异常','warning','发现问题、跟进措施，让异常有迹可循。'],['analysis','数据分析与复盘','chart','用有记录的数据，讲清项目推进与阶段成果。'],['settings','数据与设置','settings','管理本地体验数据与导入导出。']];
const loaded=window.BoardStorage.load();
let unified=loaded.data,corruptKeys=loaded.corrupt,memoryOnly=loaded.blocked;
function write(key,value){try{localStorage.setItem(key,JSON.stringify(value));}catch(e){throw Error('浏览器未能保存数据，可能存储空间不足或禁止存储。此次修改未生效。');}}
let state={date:C.today(),page:nav.some(n=>n[0]===location.hash.slice(1))?location.hash.slice(1):'overview',view:'table',project:'all',status:'all',owner:'all',priority:'all',risk:'all',sort:'deadline',query:'',detail:null,progressProject:'all',riskScope:'all'};
let reportText='',lastFocus=null,toastTimer,isComposing=false;
function dataset(){return unified;}
function cutoff(){return state.date;}
function model(){const ds=dataset(),tasks=C.snapshot(ds.tasks,cutoff(),true),records=C.visibleRisks(ds.risks,cutoff());return {ds,tasks,records,projects:C.projectList({...ds,projects:ds.projects.filter(p=>!p.createdAt||p.createdAt<=cutoff())},tasks,true),metrics:C.metrics(tasks,cutoff(),records)};}
function readonly(){return memoryOnly;}
function canEdit(){if(readonly()){toast('本地体验数据无法读取或保存；请下载备份后检查浏览器存储，或清空体验数据。');return false;}return true;}
function saveDataset(next){if(!canEdit())throw Error('数据保存未启用');next={...next,projects:C.projectList(next,next.tasks,true).map(({tasks,total,completed,rate,...p})=>p)};window.BoardStorage.validate(next);write(KEYS.unified,next);unified=next;}
function saveMeta(next){saveDataset({...dataset(),projects:next.projects,risks:next.risks});}
function dateLabel(d){return d?esc(String(d).replaceAll('-','.')):'未设置';}
function statusClass(s){return s==='已完成'||s==='已关闭'||s==='已解决 / 已关闭'?'done':s==='进行中'||s==='处理中'?'active':s==='延期'||s==='已延误'?'delayed':'';}
function status(s){return `<span class="status ${statusClass(s)}">${esc(s==='未开始'?'待开始':s==='延期'?'已延期':s)}</span>`;}
function priority(p){return `<span class="priority ${p==='urgent-important'?'high':p==='important'?'medium':''}">${esc(C.PRIORITIES[p])}</span>`;}
function track(rate,color){return `<div class="track"><span style="width:${Math.max(0,Math.min(100,rate))}%;background:${color||'var(--blue)'}"></span></div>`;}
function action(name,label,extra='',cls='button'){return `<button class="${cls}" data-action="${name}" ${extra}>${label}</button>`;}
function empty(title='暂无任务',text='新增任务，开始拆解与跟踪工作。'){const project=!model().projects.length;return `<div class="empty"><h3>${esc(title)}</h3><p>${esc(text)}</p>${action(project?'new-project':'new-task',project?'＋ 新建项目':'＋ 新增任务','','button primary')}</div>`;}
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4200);}
function warnStorage(){const el=$('#storageWarning');el.hidden=!corruptKeys.size&&!memoryOnly;if(!el.hidden)el.innerHTML=`本地体验数据无法读取或保存，编辑已停用。可先下载当前体验存储备份，检查浏览器存储权限后刷新，或清空体验数据重新开始。 ${action('raw-storage','下载体验存储备份','','text-button')} ${action('clear-data','清空我的体验数据','','text-button')}`;}
function renderSidebar(m){$('#sidebar').innerHTML=`<div class="brand"><span class="brand-mark">${icon('grid')}</span><div><strong>项目协作台<span class="version">2.0</span></strong><small>轻量化项目任务管理与进度跟踪系统</small></div></div><div class="nav-label">工作空间</div><nav aria-label="主导航">${nav.slice(0,6).map(n=>`<button class="nav-button ${state.page===n[0]?'active':''}" data-nav="${n[0]}" ${state.page===n[0]?'aria-current="page"':''}>${icon(n[2])}<span>${n[1]}</span>${n[0]==='risks'&&m.metrics.risk?`<span class="nav-count">${m.metrics.risk}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><button class="nav-button ${state.page==='settings'?'active':''}" data-nav="settings">${icon('settings')}数据与设置</button><div class="local-note">${icon('database')}<div>本地工作空间<small><span class="local-dot"></span>数据保存在此浏览器</small></div></div></div>`;}
function context(){$('#contextBar').innerHTML=`<div class="context-left"><span class="demo-badge">在线体验版</span><span class="context-divider"></span><span class="date-range muted">数据仅保存在当前浏览器，不跨设备同步</span></div><div class="context-right"><label for="customDate">统计截至</label><input aria-label="统计截至日期" id="customDate" type="date" value="${esc(state.date)}">${action('today','今天','','button small')}</div>`;$('#footer').innerHTML=`<span>项目协作台 · 轻量化项目任务管理与进度跟踪系统</span><span>统计截至 ${state.date} · 浏览器本地存储</span>`;}
function stats(m,projectCount){const a=[['项目总数',projectCount,'覆盖业务项目','folder',''],['任务总数',m.total,'截至日期已创建','list',''],['已完成任务',m.completed,'以完成状态计数','check','green'],['任务完成率',m.total?m.rate+'%':'—','已完成 / 任务总数','ring',''],['当前未结任务',m.total-m.completed,'截至日期尚未完成','play','green'],['当前未关闭风险',m.openRisks,'显式风险记录 · 未关闭','warning','orange']];return `<section class="stats-grid" aria-label="核心数据">${a.map(([label,value,note,i,color])=>`<article class="stat"><div class="stat-top"><span class="stat-icon ${color}">${icon(i)}</span>${label}</div><strong data-metric="${label}">${value}</strong><small>${note}</small></article>`).join('')}</section>`;}
function donut(m){let offset=0;const colors={'已完成':'#466be8','进行中':'#8fafff','未开始':'#d8deea','延期':'#e9ad82'};const segments=['已完成','进行中','未开始','延期'].map(s=>{const begin=offset;offset+=m.total?m.counts[s]/m.total*360:0;return `${colors[s]} ${begin}deg ${offset}deg`;});return `<div class="completion-body"><div role="img" aria-label="任务完成率 ${m.total?m.rate+'%':'暂无数据'}，已完成 ${m.completed} 项，总计 ${m.total} 项" class="donut" style="background:${m.total?'conic-gradient('+segments.join(',')+')':'#edf0f6'}"><div class="donut-inner"><strong>${m.total?m.rate+'%':'—'}</strong><small>任务完成率</small></div></div><div class="legend">${['已完成','进行中','未开始','延期'].map(s=>`<div class="legend-row"><i class="dot" style="background:${colors[s]}"></i>${s==='未开始'?'待开始':s}<b>${m.counts[s]}</b></div>`).join('')}</div></div>`;}
function monthRows(m){return C.monthly(m.tasks,cutoff());}
function bars(rows,both=false){const max=Math.max(1,...rows.flatMap(r=>both?[r.created,r.completed]:[r.completed]));return `<div class="bar-chart" role="img" aria-label="${esc(rows.map(r=>r.month+' 新增 '+r.created+'，完成 '+r.completed).join('；'))}">${rows.length?rows.map(r=>`<div class="bar-group">${both?`<div class="bar alt" style="height:${r.created/max*85}%"><b>${r.created}</b></div>`:''}<div class="bar" style="height:${r.completed/max*85}%"><b>${r.completed}</b></div><span class="bar-label">${Number(r.month.slice(5))}月</span></div>`).join(''):'<small>暂无带日期的完成记录</small>'}</div>`;}
function compare(projects){return `<div class="compare-list">${projects.map(p=>`<div><div class="compare-label"><span>${esc(p.short)}</span><b>${p.total?p.rate+'%':'—'}</b></div>${track(p.rate,p.color)}</div>`).join('')}</div>`;}
function projectDone(p){return !!p.total&&p.completed===p.total&&(!p.milestones?.length||C.milestones(p,cutoff()).every(x=>x.status==='已完成'));}
function projectCard(p){const s=projectDone(p)?'已完成':p.tasks.some(t=>t.status==='延期')?'延期':p.tasks.some(t=>t.status==='进行中'||t.status==='已完成')?'进行中':'未开始';const milestone=C.milestones(p,cutoff()).find(x=>x.status!=='已完成');return `<button class="project-card" data-project="${esc(p.id)}"><div class="project-card-top"><span class="project-symbol" style="color:${p.color}">${icon(p.icon)}</span><h3>${esc(p.short)}</h3>${status(s)}</div><p>${esc(p.description)}</p><div class="project-progress">${track(p.rate,p.color)}<strong>${p.total?p.rate+'%':'—'}</strong></div><div class="project-meta"><span>${icon('list')}${p.completed}/${p.total} 任务</span><span>${icon('people')}${esc(p.owner)}</span><span class="dates">${icon('calendar')}${dateLabel(p.start)} — ${dateLabel(p.end)}</span></div>${state.page==='projects'?`<div class="unverified">${esc(p.category)} · 当前节点：${esc(milestone?.name||(p.milestones?.length?'全部节点已交付':'未设置里程碑'))}</div>`:''}</button>`;}
function miniTable(tasks,m){return tasks.length?`<div class="table-wrap"><table class="compact-table"><thead><tr><th>任务名称</th><th>所属项目</th><th>截止日期</th><th>状态</th></tr></thead><tbody>${tasks.map(t=>`<tr><td><button class="task-name-button" data-task="${esc(t.id)}">${esc(t.name)}</button><span class="subcell">${esc(t.owner)} · ${esc(t.phaseName)}</span></td><td>${esc(m.projects.find(p=>p.id===t.projectId)?.short||t.projectName)}</td><td>${t.deadline?.slice(5)||'未设置'}</td><td>${status(t.status)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">当前没有需要处理的任务。</p>';}
function recentEvents(m){const events=m.tasks.flatMap(t=>t.history?t.history.filter(e=>e.date<=cutoff()).map((e,i)=>({...e,id:t.id,order:i,name:e.snapshot.name,projectName:e.snapshot.projectName})):t.completedAt?[{date:t.completedAt,type:'任务完成',id:t.id,name:t.name,projectName:t.projectName}]:[]);const risks=m.records.flatMap(r=>r.history.map(e=>({date:e.date,type:'风险'+e.status,name:r.title,projectName:'风险跟踪记录',risk:true})));return [...events,...risks].sort((a,b)=>b.date.localeCompare(a.date)||(b.order||0)-(a.order||0)).slice(0,5);}
function archiveBanner(m){if(!m.projects.length)return `<section class="panel welcome"><h2>欢迎使用项目协作台</h2><p>欢迎使用项目协作台。当前还没有项目，您可以创建第一个项目，体验任务拆解、进度跟踪和结果分析等功能。</p><p class="muted">创建项目 → 新增任务 → 设置负责人和日期 → 更新状态 → 查看进度及汇报</p>${action('new-project','＋ 新建项目','','button primary')}</section>`;return `<section class="panel archive-banner"><div><h2>项目推进概况 · ${cutoff()}</h2><p>从项目目标到任务交付，跟踪每一步推进。</p></div><small>当前未结任务 ${m.metrics.total-m.metrics.completed} · 未关闭风险 ${m.metrics.openRisks}</small></section>`;}



function overview(m){const focus=m.tasks.filter(t=>m.metrics.riskIds.includes(t.id)).sort((a,b)=>(a.deadline||'9999').localeCompare(b.deadline||'9999')).slice(0,4);const feed=recentEvents(m);return `${archiveBanner(m)}${stats(m.metrics,m.projects.length)}<section class="charts-grid" aria-label="项目统计图表"><article class="panel"><div class="panel-heading"><h2>任务完成率与状态分布</h2></div>${donut(m.metrics)}</article><article class="panel"><div class="panel-heading"><h2>月度已完成任务数</h2><small>共完成 ${m.metrics.completed} 项任务</small></div>${bars(monthRows(m))}<div class="chart-key"><span><i class="dot"></i> 按实际完成日期归属月份</span></div></article><article class="panel"><div class="panel-heading"><h2>各项目进度</h2><small>任务数量口径</small></div>${m.projects.length?compare(m.projects):'<p class="muted">暂无项目</p>'}</article></section><section class="panel projects-section"><div class="panel-heading"><h2>项目动态 <small> / ${m.projects.length} 个项目</small></h2><button class="text-button" data-nav="projects">查看全部 →</button></div><div class="project-grid">${m.projects.map(projectCard).join('')||empty('暂无项目','创建第一个项目，开始体验。')}</div></section><section class="bottom-grid"><article class="panel"><div class="panel-heading"><h2>当前重点任务</h2><button class="text-button" data-nav="tasks">查看全部 →</button></div>${miniTable(focus,m)}<div class="inline-notice">${icon('warning')}<span>${m.metrics.overdue} 项已逾期 · ${m.metrics.delayed} 项明确延期 · ${m.metrics.dueSoon} 项临近截止</span><button class="text-button" data-nav="risks">跟进风险 →</button></div></article><article class="panel"><div class="panel-heading"><h2>最近项目动态</h2><small>截至 ${cutoff().slice(5)}</small></div><div class="timeline-feed">${feed.map(e=>`<div class="feed-item"><span class="feed-icon">${e.risk?'!':'✓'}</span><div><p>${esc(e.type)} · ${esc(e.name)}</p><small>${esc(e.projectName)}</small></div><time>${e.date.slice(5)}</time></div>`).join('')||'<p class="muted">暂无可验证的过程记录。</p>'}</div></article></section><section class="panel"><div class="panel-heading"><h2>近期里程碑</h2><button class="text-button" data-nav="progress">查看全部 →</button></div><div class="project-grid">${m.projects.flatMap(p=>C.milestones(p,cutoff()).filter(x=>x.status!=='已完成').slice(0,1).map(x=>`<button class="project-card" data-milestone="${x.id}"><h3>${esc(x.name)}</h3><p>${esc(p.short)} · ${x.date}</p>${status(x.status)} <small>${x.done}/${x.required} 项关联任务</small></button>`)).join('')||'<p class="muted">当前没有待交付的里程碑。</p>'}</div></section>`;}
function projectDetail(p,m){const phases=p.phases.map(phase=>{const tasks=p.tasks.filter(t=>t.phaseName===phase),done=tasks.filter(t=>t.status==='已完成').length;return `<div class="phase-item"><h3>${esc(phase)}</h3>${track(tasks.length?done/tasks.length*100:0,p.color)}<p><span>${done}/${tasks.length} 项任务</span><span>${tasks.length?Math.round(done/tasks.length*100)+'%':'—'}</span></p></div>`;}).join('');const completed=p.tasks.filter(t=>t.status==='已完成');return `<div class="toolbar"><button class="text-button" data-action="back-projects">← 全部项目</button><div class="button-row">${action('edit-project','编辑项目',`data-id="${esc(p.id)}"`)}${action('delete-project','删除项目',`data-id="${esc(p.id)}"`,'button danger')}${action('project-progress','查看项目时间轴',`data-id="${esc(p.id)}"`)}</div></div><section class="panel project-detail-head"><span class="project-symbol" style="color:${p.color}">${icon(p.icon)}</span><div><h2>${esc(p.name)}</h2><p>${esc(p.goal)}</p>${p.dataNote?`<p class="unverified">${esc(p.dataNote)}</p>`:''}<div class="detail-facts"><span>负责人 ${esc(p.owner)}</span><span>${dateLabel(p.start)} — ${dateLabel(p.end)}</span><span>${esc(p.category)}</span><strong>${p.total?p.rate+'%':'—'} · ${p.completed}/${p.total} 任务</strong></div></div></section><section class="panel section-gap"><div class="panel-heading"><h2>阶段完成情况</h2>${action('new-phase','＋ 新增阶段',`data-id="${esc(p.id)}"`,'button small')}</div><div class="phase-list">${phases||'<p class="muted">暂无阶段，可新增阶段或在任务中填写阶段。</p>'}</div></section>${milestoneCards(p)}<section class="panel section-gap"><div class="panel-heading"><h2>项目任务清单</h2>${action('project-tasks','管理任务',`data-id="${esc(p.id)}"`,'text-button')}</div>${miniTable(p.tasks,m)}</section><section class="bottom-grid"><article class="panel"><div class="panel-heading"><h2>阶段成果</h2><small>${'已记录结果'}</small></div>${completed.length?completed.filter(t=>t.outcome).map(t=>`<p class="detail-record">✓ ${esc(t.outcome)}<br><small>${t.completedAt||'完成日期未记录'} · ${esc(t.name)}</small></p>`).join(''):'<p class="muted">尚无已完成任务成果。</p>'}<p class="unverified">${esc(p.dataNote||'成果内容来自项目记录。')}</p></article><article class="panel"><div class="panel-heading"><h2>项目总结与下一步</h2></div><p class="detail-record">截至 ${cutoff()}，${p.completed}/${p.total} 项任务完成，任务数量完成率 ${p.total?p.rate+'%':'—'}。<br>当前 ${p.tasks.filter(t=>m.metrics.riskIds.includes(t.id)).length} 项任务需关注。${projectDone(p)?'任务清单已全部完成，可复核成果并归档。':'优先处理阻塞与临近截止任务，核对下一节点交付。'}</p><div class="panel-heading" style="margin-top:20px"><h2>当前风险</h2><button class="text-button" data-nav="risks">查看记录 →</button></div>${p.tasks.filter(t=>m.metrics.riskIds.includes(t.id)).map(t=>`<p class="detail-record"><button data-task="${esc(t.id)}" class="text-button">${esc(t.name)}</button><br>${esc(C.riskTags(t,cutoff()).join(' · '))}</p>`).join('')||'<p class="muted">当前无规则命中的风险任务。</p>'}</article></section>`;}
function projectsPage(m){if(state.detail){const p=m.projects.find(p=>p.id===state.detail);if(p)return projectDetail(p,m);state.detail=null;}return `<div class="toolbar"><p class="muted">${m.projects.length} 个业务项目 · ${m.tasks.length} 项任务</p><div class="button-row">${action('new-project','＋ 新建项目','','button primary')}</div></div><div class="project-grid">${m.projects.map(projectCard).join('')||empty('暂无项目')}</div><div class="notice" style="margin-top:18px">点击项目查看目标、阶段拆解、里程碑、任务清单与成果。项目完成率按已完成任务数量计算，不将任务进度百分比视为项目完成率。</div>`;}
function filtered(m){return m.tasks.filter(t=>(state.project==='all'||t.projectId===state.project)&&(state.status==='all'||t.status===state.status)&&(state.owner==='all'||t.owner===state.owner)&&(state.priority==='all'||t.priority===state.priority)&&(state.risk==='all'||state.risk==='any'&&m.metrics.riskIds.includes(t.id)||C.riskTags(t,cutoff()).includes(state.risk))&&[t.name,t.projectName,t.owner,t.phaseName,t.note].some(s=>s.toLowerCase().includes(state.query.toLowerCase()))).sort((a,b)=>state.sort==='priority'?Object.keys(C.PRIORITIES).indexOf(a.priority)-Object.keys(C.PRIORITIES).indexOf(b.priority):(a.deadline||'9999').localeCompare(b.deadline||'9999')||a.name.localeCompare(b.name));}
function options(values,current,label){return `<option value="all">${label}</option>${values.map(([v,n])=>`<option value="${esc(v)}" ${current===v?'selected':''}>${esc(n)}</option>`).join('')}`;}
function taskToolbar(m){return `<div class="toolbar"><div class="filters"><input id="taskSearch" aria-label="搜索任务、项目或负责人" type="search" placeholder="搜索任务、项目或负责人…" value="${esc(state.query)}"><select aria-label="筛选项目" data-filter="project">${options(m.projects.map(p=>[p.id,p.short]),state.project,'全部项目')}</select><select aria-label="筛选状态" data-filter="status">${options(C.STATUSES.map(s=>[s,s]),state.status,'全部状态')}</select><select aria-label="筛选负责人" data-filter="owner">${options([...new Set(m.tasks.map(t=>t.owner))].map(s=>[s,s]),state.owner,'全部负责人')}</select><select aria-label="筛选优先级" data-filter="priority">${options(Object.entries(C.PRIORITIES),state.priority,'全部优先级')}</select><select aria-label="筛选风险" data-filter="risk">${options(['any','已逾期','明确延期','临近截止','高优先级待处理','阻塞事项'].map(s=>[s,s==='any'?'所有风险任务':s]),state.risk,'全部风险')}</select><select aria-label="任务排序" data-filter="sort"><option value="deadline" ${state.sort==='deadline'?'selected':''}>截止日期排序</option><option value="priority" ${state.sort==='priority'?'selected':''}>优先级排序</option></select>${action('clear-filters','重置','','text-button')}</div><div class="view-switch" aria-label="任务视图">${[['table','表格','list'],['kanban','看板','kanban'],['timeline','时间轴','timeline']].map(([v,n,i])=>`<button data-view="${v}" class="${state.view===v?'active':''}" aria-pressed="${state.view===v}">${icon(i)}${n}</button>`).join('')}</div></div>`;}
function taskTable(tasks,m){if(!tasks.length)return empty(m.tasks.length?'没有匹配的任务':'暂无任务','调整筛选条件，或创建一条新任务。');return `<section class="panel tasks-panel"><div class="table-wrap"><table><thead><tr><th>任务名称 / 阶段</th><th>所属项目</th><th>负责人</th><th>优先级</th><th>开始日期</th><th>截止日期</th><th>任务状态</th><th>任务进度</th><th>操作</th></tr></thead><tbody>${tasks.map(t=>`<tr><td><button class="task-name-button" data-task="${esc(t.id)}">${esc(t.name)}</button><span class="subcell">${esc(t.phaseName)}</span></td><td>${esc(m.projects.find(p=>p.id===t.projectId)?.short||t.projectName)}</td><td>${esc(t.owner)}</td><td>${priority(t.priority)}</td><td>${t.startDate||'未记录'}</td><td>${t.deadline||'未设置'}${C.riskTags(t,cutoff()).includes('已逾期')?'<span class="subcell" style="color:var(--red)">已逾期</span>':''}</td><td><select class="row-status ${statusClass(t.status)}" data-status-id="${esc(t.id)}" aria-label="${esc(t.name)} 状态" ${readonly()?'disabled':''}>${C.STATUSES.map(s=>`<option ${t.status===s?'selected':''}>${s}</option>`).join('')}</select></td><td><div class="mini-progress">${track(t.progress)}${t.progress}%</div></td><td><div class="row-actions"><button data-action="edit-task" data-id="${esc(t.id)}">编辑</button><button data-action="delete-task" data-id="${esc(t.id)}">删除</button></div></td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>显示 ${tasks.length} / ${m.tasks.length} 项任务 · 任务进度由负责人记录</span><div class="button-row">${action('export-csv','导出当前筛选 CSV','','button small')}${action('export-json','导出完整 JSON','','button small')}</div></div></section>`;}
function kanban(tasks,m){return `<div class="notice">${readonly()?'历史视角只读。':'拖拽卡片或使用卡片中的状态菜单更新任务，所有视图与统计即时同步。'} “已延期”是明确标记的状态；自动逾期仍保留原状态并由风险规则识别。</div><div class="kanban">${C.STATUSES.map(s=>`<section class="kanban-column" data-drop-status="${s}"><h2 class="kanban-heading">${status(s)}<b>${tasks.filter(t=>t.status===s).length}</b></h2>${tasks.filter(t=>t.status===s).map(t=>`<article class="kanban-task" draggable="${!readonly()}" data-drag-id="${esc(t.id)}">${priority(t.priority)}<h3><button class="task-name-button" data-task="${esc(t.id)}">${esc(t.name)}</button></h3><p>${esc(m.projects.find(p=>p.id===t.projectId)?.short||t.projectName)} · ${esc(t.phaseName)}</p>${track(t.progress)}<div class="task-bottom"><span>${esc(t.owner)} · ${t.deadline?.slice(5)||'未设置'}</span><select class="row-status" data-status-id="${esc(t.id)}" aria-label="${esc(t.name)} 状态" ${readonly()?'disabled':''}>${C.STATUSES.map(v=>`<option ${v===s?'selected':''}>${v}</option>`).join('')}</select></div></article>`).join('')||'<p class="muted" style="font-size:10px;padding:12px 4px">此列暂无任务</p>'}</section>`).join('')}</div>`;}
function gantt(tasks){const dated=tasks.filter(t=>t.startDate&&t.deadline).sort((a,b)=>a.projectName.localeCompare(b.projectName)||a.startDate.localeCompare(b.startDate));if(!dated.length)return empty('创建任务后可查看项目排期','请为任务填写开始日期和截止日期。');const dates=dated.flatMap(t=>[t.startDate,t.deadline]);const min=dates.sort()[0],max=dates.sort().at(-1);const span=Math.max(1,(Date.parse(max)-Date.parse(min))/86400000+1);const pos=d=>(Date.parse(d)-Date.parse(min))/86400000/span*100;const months=[];let d=new Date(min+'T00:00:00Z');d.setUTCDate(1);for(let i=0;i<36&&d.toISOString().slice(0,10)<=max;i++){months.push(d.toISOString().slice(0,7));d.setUTCMonth(d.getUTCMonth()+1);}const arrows=dated.flatMap((t,i)=>t.dependencies.map(id=>{const j=dated.findIndex(x=>x.id===id);if(j<0)return '';const x1=Math.min(99,pos(dated[j].deadline)+100/span),x2=Math.max(0,pos(t.startDate)),y1=j*58+23,y2=i*58+23;return `<path d="M ${x1*10} ${y1} H ${Math.min(995,x1*10+10)} V ${y2} H ${x2*10}" fill="none" stroke="#a5b5d5" stroke-width="1.2" marker-end="url(#arrow)"/>`;})).join('');return `<div class="gantt-wrap"><div class="gantt"><div class="gantt-header"><div class="gantt-label">任务 / 项目阶段</div><div class="gantt-months">${months.map(s=>`<span>${s.replace('-',' 年 ')} 月</span>`).join('')}</div></div>${dated.map(t=>`<div class="gantt-row" style="height:58px"><div class="gantt-label"><button class="task-name-button" data-task="${esc(t.id)}">${esc(t.name)}</button><small>${esc(t.phaseName)} · ${esc(t.owner)} · ${t.startDate.slice(5)} → ${t.deadline.slice(5)}</small></div><div class="gantt-lane"><button class="gantt-bar ${statusClass(t.status)}" style="left:${Math.max(0,pos(t.startDate))}%;width:${Math.max(1,Math.min(100-pos(t.startDate),((Date.parse(t.deadline)-Date.parse(t.startDate))/86400000+1)/span*100))}%" data-task="${esc(t.id)}" title="${esc(t.name)} ${t.startDate} 至 ${t.deadline} · ${t.progress}%"><i style="width:${t.progress}%"></i><span>${t.progress}%</span></button></div></div>`).join('')}<svg class="gantt-arrows" viewBox="0 0 1000 ${dated.length*58}" preserveAspectRatio="none" aria-label="任务依赖关系"><defs><marker id="arrow" markerWidth="5" markerHeight="5" refX="4" refY="2.5" orient="auto"><path d="M0 0L5 2.5L0 5" fill="#9bafd4"/></marker></defs>${arrows}</svg></div><div class="gantt-key"><span>时间范围 ${min} — ${max}</span><span>箭头 → 关联前置任务</span><span>深色填充 = 任务进度</span><span>${tasks.length-dated.length} 项缺少日期未显示</span></div></div>`;}
function tasksPage(m){const tasks=filtered(m);return `${readonly()?'<div class="notice">本地存储待检查，编辑和拖拽暂不可用。请先下载原始存储备份。</div>':''}${taskToolbar(m)}${state.view==='table'?taskTable(tasks,m):state.view==='kanban'?kanban(tasks,m):gantt(tasks)}`;}
function milestoneCards(p){const nodes=C.milestones(p,cutoff());return `<section class="section-gap"><div class="panel-heading"><h2>关键里程碑</h2><div class="button-row"><small>关联任务全部完成即交付</small>${action('new-milestone','＋ 新增里程碑',`data-id="${esc(p.id)}"`,'button small')}</div></div><div class="milestone-grid">${nodes.map((x,i)=>`<button class="milestone" data-milestone="${esc(x.id)}"><div class="milestone-id">M${i+1}<span>${x.done}/${x.required}</span></div><h3>${esc(x.name)}</h3><small>${x.date}</small>${status(x.status)}</button>`).join('')||'<p class="muted">暂无里程碑，新增任务后可关联关键交付节点。</p>'}</div></section>`;}
function progressPage(m){const ps=state.progressProject==='all'?m.projects:m.projects.filter(p=>p.id===state.progressProject);return `<div class="toolbar"><div class="filters"><select id="progressProject" aria-label="进度项目">${options(m.projects.map(p=>[p.id,p.short]),state.progressProject,'全部项目')}</select></div><small class="muted">任务数量完成率 · 截至 ${cutoff()}</small></div>${ps.map(p=>`<section class="panel section-gap"><div class="panel-heading"><h2>${esc(p.name)}</h2><strong>${p.total?p.rate+'%':'—'}</strong></div>${track(p.rate,p.color)}<p class="unverified">${p.completed}/${p.total} 任务完成 · ${C.milestones(p,cutoff()).filter(x=>x.status==='已完成').length}/${p.milestones?.length||0} 里程碑交付 · 下一步：${esc(p.tasks.find(t=>t.status!=='已完成')?.name||'复核交付成果并归档')}</p></section>${milestoneCards(p)}`).join('')}<section class="section-gap"><div class="panel-heading"><h2>任务时间轴与依赖</h2><small>点击条形查看任务与前置事项</small></div>${gantt(ps.flatMap(p=>p.tasks))}</section>`;}
function riskModels(m){const list=m.records.filter(r=>m.tasks.some(t=>t.id===r.taskId)).map(r=>({...r,task:m.tasks.find(t=>t.id===r.taskId),tags:C.riskTags(m.tasks.find(t=>t.id===r.taskId),cutoff()),record:true}));m.tasks.forEach(t=>{const tags=C.riskTags(t,cutoff());if(tags.length&&!list.some(r=>r.taskId===t.id))list.push({id:'auto-'+t.id,taskId:t.id,title:t.name,task:t,tags,cause:tags.includes('已逾期')?'任务已过原定截止时间，尚未完成。':tags.includes('阻塞事项')?'任务被标记为阻塞，需要协调前置事项。':tags.includes('临近截止')?'任务在统计日未来三天内到期，尚未完成。':'高优先级任务尚未完成，或被明确标记延期。',impact:m.projects.flatMap(p=>C.milestones(p,cutoff())).find(x=>x.tasks.some(k=>k.id===t.id))?.name||t.phaseName,action:'确认剩余工作与前置条件，协调责任角色，记录处理措施及预计完成时间。',owner:t.owner,status:'待处理',history:[],record:false});});return list;}
function risksPage(m){let risks=riskModels(m);if(state.riskScope==='open')risks=risks.filter(r=>r.status!=='已关闭');if(state.riskScope==='closed')risks=risks.filter(r=>r.status==='已关闭');return `<div class="toolbar"><h2>风险记录</h2>${action('new-risk','＋ 记录任务风险','','button primary')}</div><div class="notice">风险任务按任务 ID 去重；“明确延期”“自动逾期”“临近截止”分别判断，可同时命中。关闭处理记录不会自动完成任务，截止风险仍按任务实际状态展示。</div><div class="toolbar"><div class="view-switch">${[['all','全部记录'],['open','待跟进'],['closed','已关闭案例']].map(([v,n])=>`<button data-risk-scope="${v}" class="${state.riskScope===v?'active':''}">${n}</button>`).join('')}</div><small class="muted">${m.metrics.risk} 项风险任务 · ${m.metrics.overdue} 项已逾期 · ${m.metrics.delayed} 项明确延期 · ${m.metrics.dueSoon} 项临近截止</small></div><div class="risk-grid">${risks.map(r=>`<article class="panel risk-card ${r.status==='已关闭'?'closed':''}"><div class="risk-card-title"><h3>${esc(r.title)}</h3>${status(r.status==='已关闭'?'已解决 / 已关闭':r.status)}</div><small>${esc(r.task.projectName)} · ${esc(r.owner)}</small><div class="risk-tags">${r.tags.map(t=>`<span class="risk-tag">${esc(t)}</span>`).join('')||'<span class="risk-tag" style="color:var(--teal);background:#ecf9f4">已完成处理闭环</span>'}</div><dl class="risk-facts"><dt>关联任务</dt><dd><button class="text-button" data-task="${esc(r.taskId)}">${esc(r.task.name)}</button></dd><dt>关联准备项</dt><dd>${(r.relatedTaskIds||[r.taskId]).map(id=>m.tasks.find(t=>t.id===id)).filter(Boolean).map(t=>`<button class="text-button" data-task="${esc(t.id)}">${esc(t.name)}</button>`).join('；')}</dd><dt>风险原因</dt><dd>${esc(r.cause)}</dd><dt>影响节点</dt><dd>${esc(r.impact)}</dd><dt>处理建议</dt><dd>${esc(r.action)}</dd><dt>任务截止</dt><dd>${r.task.deadline||'未设置'} · ${esc(r.owner)}</dd></dl><div class="risk-history">${r.history.map(e=>`<p><time>${esc(e.date)}</time><strong>${esc(e.status)}</strong> · ${esc(e.note)}</p>`).join('')||'<p>由当前任务规则识别，尚未记录处理过程。</p>'}</div><div class="risk-actions">${action('risk-update',r.status==='已关闭'?'补充处理记录':'记录处理 / 关闭',`data-id="${esc(r.id)}"`,'button small')}${action('edit-task','更新任务',`data-id="${esc(r.taskId)}"`,'text-button')}</div></article>`).join('')||empty('当前范围没有风险记录','切换记录范围查看其他处理情况。')}</div>`;}
function analysisPage(m){const months=monthRows(m);return `${!m.tasks.length?'<section class="panel welcome"><h2>暂无可分析的数据</h2><p>创建任务并更新状态后，可查看任务分布、项目完成率与周报。</p></section>':archiveBanner(m)}${stats(m.metrics,m.projects.length)}<div class="analysis-grid"><article class="panel"><div class="panel-heading"><h2>月度新增与完成任务</h2><small>累计完成率按该月末已创建任务计算，受当前回放日期限制</small></div>${m.tasks.length?donut(m.metrics):''}${bars(months,true)}<div class="chart-key"><span><i class="dot" style="background:#d7e2ff"></i> 新增任务</span><span><i class="dot"></i> 完成任务</span></div><div class="table-wrap" style="margin-top:20px"><table class="analysis-table"><thead><tr><th>月份</th><th>当月新增</th><th>当月完成</th><th>累计完成</th><th>累计完成率</th></tr></thead><tbody>${months.map(r=>`<tr><td>${r.month}</td><td>${r.created}</td><td>${r.completed}</td><td>${r.cumulative}</td><td>${r.cumulativeRate}%</td></tr>`).join('')}</tbody></table></div></article><article class="panel"><div class="panel-heading"><h2>完成质量与当前风险</h2><small>对比原计划截止日期</small></div><div class="compare-list" style="display:grid;grid-template-columns:1fr">${[['按期完成',m.metrics.ontime,'#25a894'],['逾期完成',m.metrics.late,'#dca06b'],['完成日期 / 原计划缺失',m.metrics.unknown,'#acb8cd'],['当前风险任务',m.metrics.risk,'#d86b51']].map(([n,v,color])=>`<div><div class="compare-label"><span>${n}</span><b>${v} 项</b></div>${track(m.metrics.total?v/m.metrics.total*100:0,color)}</div>`).join('')}</div><p class="unverified" style="margin-top:24px">旧版已完成任务若缺少完成日期，保留完成状态；不推测完成月份或是否按期。当前风险数包含临近截止，分类可能重叠，合计按任务去重。</p></article></div><section class="panel section-gap"><div class="panel-heading"><h2>项目阶段交付情况</h2><small>项目完成率以已完成任务数量计算</small></div><div class="table-wrap"><table><thead><tr><th>项目</th><th>已完成 / 总任务</th><th>完成率</th><th>已交付里程碑</th><th>风险任务</th></tr></thead><tbody>${m.projects.map(p=>`<tr><td><button class="text-button" data-project="${esc(p.id)}">${esc(p.short)}</button></td><td>${p.completed}/${p.total}</td><td>${p.total?p.rate+'%':'—'}</td><td>${C.milestones(p,cutoff()).filter(x=>x.status==='已完成').length}/${p.milestones?.length||0}</td><td>${p.tasks.filter(t=>m.metrics.riskIds.includes(t.id)).length}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-heading"><div><h2>成果总结与项目汇报</h2><small>仅引用当前统计范围内的记录</small></div><div class="button-row">${action('generate-report','生成阶段汇报','','button primary small')}${action('weekly-report','生成周报','','button small')}${action('copy-report','复制','','button small')}</div></div><label class="sr-only" for="reportText">可复制的项目汇报</label><textarea id="reportText" class="report-area" placeholder="点击「生成阶段汇报」或「生成周报」，从当前数据整理项目情况、完成工作、关键节点、问题、措施和下一步。">${esc(reportText)}</textarea><p class="unverified">不会推断节省工时、成本收益或效率提升百分比。</p></section>`;}
function settingsPage(m){return `<div class="settings-grid"><section class="panel"><h2>数据导入与导出</h2><p>完整 JSON 备份项目、任务历史与风险；CSV 导出当前统计日期的任务快照。文件在浏览器中生成和读取，不上传服务器。</p><div class="button-row">${action('export-json','导出完整 JSON','','button primary')}${action('export-all-csv','导出 CSV')}${action('import','导入 JSON / CSV')}</div><p>${m.ds.projects.length} 个项目 · ${m.ds.tasks.filter(t=>!t.deleted).length} 条任务记录</p></section><section class="panel"><h2>体验数据与隐私</h2><p>首次访问从空白开始。数据只保存在当前浏览器中，刷新后保留；不同浏览器和设备不自动同步。不提供注册登录，不上传任务信息。</p><p>公开体验版使用独立存储键，禁止自动读取其他版本的数据。同域名下的存储命名空间属于应用层隔离，并非浏览器来源级隔离；需要严格隔离时应使用不同域名。</p></section><section class="panel"><h2>清空我的体验数据</h2><p>清空此公开体验版在当前浏览器创建的全部项目、任务、风险及历史，恢复空白。清空前建议导出 JSON 备份。</p>${action('clear-data','清空我的体验数据','','button danger')}</section><section class="panel"><h2>统计口径与使用帮助</h2><p>项目完成率 = 已完成任务数 / 任务总数。没有任务时显示 —。所有页面使用同一统计日期；任务历史按记录日期回放，不推测缺失日期。</p><p>临近截止提醒为统计日期起三天内；已过截止且尚未完成的任务判为逾期。关闭风险记录不会自动完成任务。</p>${action('help','操作说明','','button small')}</section></div>`;}
function render(){const m=model();renderSidebar(m);const n=nav.find(n=>n[0]===state.page)||nav[0];$('#pageTitle').textContent=state.page==='overview'?'项目总览':n[1];$('#breadcrumb').textContent=n[1];$('#pageSubtitle').textContent=state.page==='overview'?'轻量化项目任务管理与进度跟踪系统':n[3];context();warnStorage();$('#content').innerHTML=({overview,projects:projectsPage,tasks:tasksPage,progress:progressPage,risks:risksPage,analysis:analysisPage,settings:settingsPage}[state.page]||overview)(m);const add=$('.heading-actions button');add.dataset.action=['overview','projects'].includes(state.page)?'new-project':'new-task';add.textContent=['overview','projects'].includes(state.page)?'＋ 新建项目':'＋ 新增任务';document.querySelectorAll('#content [data-action]').forEach(el=>{if(['new-task','edit-task','delete-task','new-project','edit-project','delete-project','new-phase','new-milestone','new-risk','risk-update','import'].includes(el.dataset.action)){el.disabled=readonly();if(readonly())el.title='请先检查本地存储并下载原始备份';}});}
function resetFilters(){state.query='';state.project='all';state.status='all';state.owner='all';state.priority='all';state.risk='all';state.sort='deadline';}
function navigate(page){if(state.page==='analysis'&&$('#reportText'))reportText=$('#reportText').value;state.page=page;state.detail=null;location.hash=page;$('#sidebar').classList.remove('open');render();window.scrollTo({top:0,behavior:'instant'});}
function modal(title,body,footer=''){lastFocus=document.activeElement;$('#modalContent').innerHTML=`<div class="modal-header"><h2 id="modalTitle">${esc(title)}</h2><button data-action="close-modal" class="icon-button" aria-label="关闭对话框">×</button></div>${body}${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){$('#modal').close();}
$('#modal').addEventListener('close',()=>lastFocus?.isConnected&&lastFocus.focus());
function formField(label,name,type,value,extra='',full=false){return `<label class="form-field ${full?'full':''}">${label}<input name="${name}" type="${type}" value="${esc(value||'')}" ${extra}></label>`;}
function taskEditor(id){if(!canEdit())return;const m=model(),task=m.tasks.find(t=>t.id===id);if(!m.projects.length){newProject();return;}const defaults={name:'',projectName:state.project!=='all'?m.projects.find(p=>p.id===state.project)?.name||'':m.projects[0]?.name||'',phaseName:'常规跟进事项',owner:'',phaseOwner:'',status:'未开始',priority:'normal',startDate:cutoff(),deadline:cutoff(),progress:0,note:'',outcome:'',dependencies:[],blocked:false};const t=task||defaults;modal(task?'编辑任务':'新增任务',`<form id="taskForm" data-id="${esc(id||'')}" class="modal-body"><div class="form-grid">${formField('任务名称 *','name','text',t.name,'required maxlength="100"',true)}<label class="form-field">所属项目 *<input name="projectName" value="${esc(t.projectName)}" list="projectNames" required maxlength="100"><datalist id="projectNames">${m.projects.map(p=>`<option value="${esc(p.name)}">`).join('')}</datalist></label>${formField('所属阶段 *','phaseName','text',t.phaseName,'required maxlength="60" list="phaseNames"')}<datalist id="phaseNames">${[...new Set(m.projects.flatMap(p=>p.phases))].map(n=>`<option value="${esc(n)}">`).join('')}</datalist>${formField('任务负责人 *','owner','text',t.owner,'required maxlength="40"')}${formField('阶段负责人','phaseOwner','text',t.phaseOwner,'maxlength="40"')}${formField('开始日期','startDate','date',t.startDate)}${formField('计划截止日期','deadline','date',t.deadline)}<label class="form-field">任务状态<select name="status">${C.STATUSES.map(s=>`<option ${t.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="form-field">优先级<select name="priority">${Object.entries(C.PRIORITIES).map(([v,n])=>`<option value="${v}" ${t.priority===v?'selected':''}>${n}</option>`).join('')}</select></label>${formField('任务进度（0–100）','progress','number',String(t.progress),'min="0" max="100" required')}${formField('实际完成日期（完成时必填）','completedAt','date',t.completedAt||'')}<label class="form-field full">前置任务（同项目，可多选）<select name="dependencies" multiple size="3">${m.tasks.filter(k=>k.id!==t.id).map(k=>`<option value="${esc(k.id)}" ${t.dependencies.includes(k.id)?'selected':''}>${esc(k.name)} · ${esc(k.projectName)}</option>`).join('')}</select></label><label class="form-field full">备注 / 异常原因<textarea name="note" maxlength="2000">${esc(t.note)}</textarea></label><label class="form-field full">工作成果描述<textarea name="outcome" maxlength="2000">${esc(t.outcome)}</textarea></label><label class="form-field full"><span><input style="width:auto;min-height:0" name="blocked" type="checkbox" ${t.blocked?'checked':''}> 存在阻塞事项</span></label></div><p class="field-hint">${'修改记入当前统计日 '+cutoff()+'；已有历史快照保留。旧任务不推测缺失日期。'} 修改截止日期保留原计划日期，用于按期完成分析。</p><p id="formError" class="form-error" role="alert"></p><div class="modal-footer" style="padding:15px 0 0;margin-top:12px">${action('close-modal','取消')}<button type="submit" class="button primary">保存任务</button></div></form>`);}
function commitTask(form){const f=new FormData(form),id=form.dataset.id,ds=dataset(),existing=ds.tasks.find(t=>t.id===id),m=model();const name=String(f.get('name')).trim(),projectName=String(f.get('projectName')).trim(),owner=String(f.get('owner')).trim(),phaseName=String(f.get('phaseName')).trim();if(!name||!projectName||!owner||!phaseName)throw Error('请填写任务名称、项目、阶段及负责人。');const startDate=f.get('startDate'),deadline=f.get('deadline'),s=f.get('status'),completedAt=s==='已完成'?(f.get('completedAt')||(existing?.status==='已完成'?existing.completedAt:null)||(!existing||existing.status!=='已完成'?cutoff():null)):null;if(startDate&&deadline&&startDate>deadline)throw Error('截止日期不能早于开始日期。');if(completedAt&&(!C.validDate(completedAt)||completedAt>cutoff()||startDate&&completedAt<startDate))throw Error('实际完成日期应在开始日期和统计截至日期之间。');if(s==='进行中'&&startDate>cutoff())throw Error('尚未到开始日期，不能设为进行中。');const dependencies=f.getAll('dependencies');const newId=id||C.uid();const proj=m.projects.find(p=>p.name===projectName);let projectId=proj?.id||existing?.projectId||'user-'+C.uid();if(existing&&existing.projectName!==projectName&&!proj)projectId='user-'+C.uid();const adj=new Map(ds.tasks.map(t=>[t.id,t.id===id?dependencies:t.dependencies||[]]));adj.set(newId,dependencies);function cycle(node,seen){if(seen.has(node))return true;const next=new Set(seen);next.add(node);return (adj.get(node)||[]).some(dep=>cycle(dep,next));}if(cycle(newId,new Set()))throw Error('前置任务形成循环依赖，请调整。');if(dependencies.some(dep=>m.tasks.find(t=>t.id===dep)?.projectId!==projectId))throw Error('前置任务必须属于同一项目。');const changes={name,projectName,projectId,owner,phaseName,phaseOwner:String(f.get('phaseOwner')).trim()||owner,startDate,deadline,status:s,priority:f.get('priority'),progress:s==='已完成'?100:s==='未开始'?0:Math.min(99,Number(f.get('progress'))),completedAt,note:String(f.get('note')),outcome:String(f.get('outcome')),dependencies,blocked:f.has('blocked')};let next;if(existing){next=C.updateTask(existing,changes,cutoff());}else{next=C.normalize({...changes,id:newId,createdAt:cutoff(),originalDeadline:deadline,isDemo:false});const snap={...next};next.history=[{date:cutoff(),type:'任务创建',snapshot:snap}];}
const tasks=existing?ds.tasks.map(t=>t.id===id?next:t):[...ds.tasks,next];saveDataset({...ds,tasks});closeModal();reportText='';render();toast(existing?'任务已保存，关联视图已同步':'任务已创建');}
function taskDetail(id){const m=model(),t=m.tasks.find(t=>t.id===id);if(!t)return;const dependencies=t.dependencies.map(k=>m.tasks.find(t=>t.id===k)?.name||'关联任务已删除');const events=(t.history||[]).filter(e=>e.date<=cutoff()).sort((a,b)=>a.date.localeCompare(b.date));modal(t.name,`<div class="modal-body"><p>${status(t.status)} ${priority(t.priority)} <span class="muted">进度 ${t.progress}%</span></p><dl class="risk-facts"><dt>所属项目</dt><dd>${esc(t.projectName)}</dd><dt>阶段 / 角色</dt><dd>${esc(t.phaseName)} / ${esc(t.owner)}</dd><dt>任务目标</dt><dd>${esc(t.goal||'按任务说明推进工作。')}</dd><dt>工作事项</dt><dd>${esc(t.work||t.note||'待补充工作事项')}</dd><dt>创建日期</dt><dd>${t.createdAt||'未记录'}</dd><dt>计划交付</dt><dd>${esc(t.plannedOutcome||t.outcome||'未填写')}</dd><dt>计划时间</dt><dd>${t.startDate||'未记录'} → ${t.deadline||'未设置'}</dd><dt>原计划截止</dt><dd>${t.originalDeadline||'未记录'}</dd><dt>实际完成</dt><dd>${t.completedAt||'未记录'}</dd><dt>前置任务</dt><dd>${esc(dependencies.join('；')||'无')}</dd><dt>备注</dt><dd>${esc(t.note||'暂无')}</dd><dt>成果记录</dt><dd>${esc(t.status==='已完成'?t.outcome||'未填写':t.plannedOutcome?'计划结果：'+t.plannedOutcome:'尚未完成')}</dd><dt>当前风险</dt><dd>${esc(C.riskTags(t,cutoff()).join('、')||'无规则命中')}</dd></dl><h3 style="margin-bottom:12px">过程记录</h3><div class="timeline-feed">${events.map(e=>`<div class="feed-item"><span class="feed-icon">•</span><div><p>${esc(e.type)} · ${esc(e.snapshot.status)} · ${e.snapshot.progress}%</p><small>${esc(e.snapshot.note||'')}</small></div><time>${e.date}</time></div>`).join('')||'<p class="muted">普通用户任务不补造历史事件。</p>'}</div><p class="unverified">任务和成果内容来自当前浏览器的用户输入。</p></div>`,action('close-modal','关闭')+(readonly()?'':action('edit-task','编辑任务',`data-id="${esc(t.id)}"`,'button primary')));}
function setTaskStatus(id,statusValue){if(!canEdit()){render();return;}const ds=dataset(),m=model(),task=m.tasks.find(t=>t.id===id);if(!task)return;const changes={status:statusValue,progress:statusValue==='已完成'?100:statusValue==='未开始'?0:task.status==='已完成'?50:Math.max(10,task.progress),completedAt:statusValue==='已完成'?task.completedAt||cutoff():null};if(statusValue==='进行中'&&task.startDate>cutoff())throw Error('尚未到任务开始日期，请先调整日期。');const tasks=ds.tasks.map(t=>t.id===id?C.updateTask(t,changes,cutoff(),'状态更新'):t);saveDataset({...ds,tasks});reportText='';render();toast('任务状态已同步更新');}
function deleteTask(id){if(!canEdit())return;const m=model(),t=m.tasks.find(t=>t.id===id);if(!t)return;const dependents=m.tasks.filter(t=>t.dependencies.includes(id));const milestone=m.projects.flatMap(p=>C.milestones(p,cutoff())).find(x=>x.tasks.some(t=>t.id===id));modal('删除任务',`<div class="modal-body"><p>确认删除「${esc(t.name)}」？</p><p class="detail-record">${dependents.length?'同时移除 '+dependents.length+' 条任务中的前置引用。':''}${milestone?'任务关联里程碑将保持未交付，避免删除后误判完成。':''}${'已有历史快照仍可查看，完整记录可通过 JSON 备份恢复。'}</p></div>`,action('close-modal','取消')+action('confirm-delete','确认删除',`data-id="${esc(id)}"`,'button danger'));}
function confirmDelete(id){const ds=dataset();const tasks=ds.tasks.map(t=>t.id===id?C.updateTask(t,{deleted:true},cutoff(),'任务删除'):t.dependencies?.includes(id)?C.updateTask(t,{dependencies:t.dependencies.filter(k=>k!==id)},cutoff(),'前置任务移除'):t);saveDataset({...ds,tasks});closeModal();reportText='';render();toast('任务已删除');}
function milestoneDetail(id){const m=model();for(const p of m.projects){const x=C.milestones(p,cutoff()).find(x=>x.id===id);if(x){modal(x.name,`<div class="modal-body"><p>${status(x.status)} <span class="muted">${esc(p.short)} · 计划 ${x.date}</span></p><p class="detail-record">${x.done}/${x.required} 项关联任务完成。${x.tasks.length<x.required?'部分关联任务尚未创建或已删除，仍保留原交付要求。':''}</p>${miniTable(x.tasks,m)}</div>`,action('close-modal','关闭'));return;}}}
function riskEditor(id){if(!canEdit())return;const r=riskModels(model()).find(r=>r.id===id);if(!r)return;modal('风险处理记录',`<form class="modal-body" id="riskForm" data-id="${esc(id)}"><h3>${esc(r.title)}</h3><p class="unverified">记录日期：${cutoff()} · ${esc(r.owner)}</p><label class="form-field" style="margin-top:15px">处理状态<select name="status">${['待处理','处理中','已关闭'].map(s=>`<option ${r.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="form-field" style="margin-top:15px">处理措施 / 关闭结果 *<textarea required name="note" maxlength="2000" class="risk-result" placeholder="记录已协调事项、解决结果或下一步跟进安排"></textarea></label><p class="field-hint">仅记录处理结果，任务状态需单独更新；仍然逾期的任务将继续计入风险。</p><p id="formError" class="form-error" role="alert"></p><div class="modal-footer">${action('close-modal','取消')}<button type="submit" class="button primary">保存处理记录</button></div></form>`);}
function commitRisk(form){const id=form.dataset.id,r=riskModels(model()).find(r=>r.id===id),f=new FormData(form),note=String(f.get('note')).trim();if(!note)throw Error('请填写处理措施或关闭结果。');const entry={date:cutoff(),status:f.get('status'),note};const ds=dataset();const record=r.record?{...ds.risks.find(k=>k.id===id),history:[...ds.risks.find(k=>k.id===id).history,entry]}:{id:r.id,taskId:r.taskId,title:r.title,cause:r.cause,impact:r.impact,action:r.action,owner:r.owner,history:[entry]};const risks=r.record?ds.risks.map(k=>k.id===id?record:k):[...ds.risks,record];saveDataset({...ds,risks});closeModal();reportText='';render();toast('处理记录已保存');}
function report(weekly=false){const m=model();if(!m.tasks.length){reportText='当前没有可汇总的任务记录';if(state.page!=='analysis')navigate('analysis');else render();return;}const date=cutoff(),start=new Date(Date.parse(date+'T00:00:00Z')-6*86400000).toISOString().slice(0,10),completed=m.tasks.filter(t=>t.status==='已完成'&&(!weekly||t.completedAt&&t.completedAt>=start&&t.completedAt<=date)),nodes=m.projects.flatMap(p=>C.milestones(p,date).filter(x=>x.status==='已完成').map(x=>p.short+' · '+x.name)),risks=riskModels(m).filter(r=>r.status!=='已关闭'||r.tags.length),measures=m.records.flatMap(r=>r.history.filter(e=>e.date<=date&&(!weekly||e.date>=start)).map(e=>e.date+' '+r.title+'：'+e.note+'（'+e.status+'）')),next=m.tasks.filter(t=>t.status!=='已完成').sort((a,b)=>(a.deadline||'9999').localeCompare(b.deadline||'9999'));reportText=['【体验项目 · 基于本地记录】',weekly?`项目周报｜${start} 至 ${date}`:`项目阶段汇报｜截至 ${date}`,'',`一、项目整体情况\n共 ${m.projects.length} 个项目、${m.metrics.total} 项任务；已完成 ${m.metrics.completed} 项，完成率 ${m.metrics.rate}%。进行中 ${m.metrics.counts['进行中']} 项，待开始 ${m.metrics.counts['未开始']} 项，明确延期 ${m.metrics.delayed} 项。\n${m.projects.map(p=>p.short+'：'+p.completed+'/'+p.total+' 项完成（'+p.rate+'%）').join('；')}。`,'',`二、${weekly?'本周已完成的工作':'已完成的工作'}\n${completed.length?completed.map(t=>'• '+(t.completedAt||'日期未记录')+' '+t.name+'｜'+(t.outcome||'成果未填写')).join('\n'):'此范围暂无带日期的完成记录。'}`,'',`三、关键里程碑（截至日期累计）\n${nodes.length?nodes.map(s=>'• '+s).join('\n'):'尚无已交付的里程碑。'}`,'',`四、当前问题\n风险任务 ${m.metrics.risk} 项（去重）：自动逾期 ${m.metrics.overdue} 项、明确延期 ${m.metrics.delayed} 项、临近截止 ${m.metrics.dueSoon} 项，类别可重叠。\n${risks.map(r=>'• '+r.task.name+'｜'+r.cause+'｜负责人：'+r.owner+'｜'+r.status).join('\n')||'当前无风险记录。'}`,'',`五、已采取措施\n${measures.map(s=>'• '+s).join('\n')||'此范围尚无处理措施记录；建议措施不作为已采取措施。'}`,'',`六、下一阶段安排\n${next.map(t=>'• '+t.name+'｜'+t.owner+'｜计划截止 '+(t.deadline||'未设置')+(t.blocked?'｜先解除阻塞':'')).join('\n')||'当前任务清单已完成，可核对交付成果与归档资料。'}`,'',`项目复盘与成果（仅已结项项目）：\n${m.projects.filter(projectDone).map(p=>p.name+'：'+(p.result||'未填写')+'\n复盘：'+(p.review?.learning||'未填写')).join('\n')||'尚无已结项项目。'}`,`统计口径：任务数量完成率 = 已完成 / 截至日期已创建任务。按期 ${m.metrics.ontime} 项、逾期完成 ${m.metrics.late} 项，缺少完成日期或原截止日期 ${m.metrics.unknown} 项；月度趋势按实际完成日期归属。不推断工时、成本或效率收益。`,'数据说明：仅汇总当前浏览器的项目记录；未记录的日期、成果与措施不作推断。'].join('\n');if(state.page!=='analysis')navigate('analysis');else render();toast(weekly?'项目周报已生成':'阶段汇报已生成');}
async function copyReport(){const text=$('#reportText')?.value||reportText;if(!text){toast('请先生成一份汇报');return;}try{await navigator.clipboard.writeText(text);toast('汇报已复制');}catch(e){const input=$('#reportText');input?.focus();input?.select();if(document.execCommand('copy'))toast('汇报已复制');else toast('浏览器未允许复制；已选中文本，请手动复制。');}}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function exportJSON(){const ds=dataset();download(JSON.stringify({format:'project-board-v2',version:2,workspace:'public-demo',exportedAt:new Date().toISOString(),asOf:cutoff(),...ds},null,2),`项目协作台-体验项目-${cutoff()}.json`,'application/json;charset=utf-8');toast('体验项目完整 JSON 备份已导出');}
function exportCSV(all=false){const m=model(),tasks=all||state.page!=='tasks'?m.tasks:filtered(m);download(C.csv(tasks),`项目任务快照-体验项目-${cutoff()}.csv`,'text/csv;charset=utf-8');toast('任务快照 CSV 已导出');}
function rawStorage(){const data={};Object.values(KEYS).forEach(k=>{try{data[k]=localStorage.getItem(k);}catch(e){data[k]='无法读取';}});download(JSON.stringify(data,null,2),'项目协作台-原始存储备份.json','application/json');}
function validateTask(t){if(!t||typeof t!=='object'||typeof (t.name||t.taskName)!=='string'||!(t.name||t.taskName).trim())throw Error('导入任务必须有有效名称。');for(const key of ['startDate','deadline','originalDeadline','createdAt','completedAt']){if(t[key]&&!C.validDate(C.day(t[key])))throw Error('任务日期无效：'+key);}if(t.startDate&&t.deadline&&C.day(t.startDate)>C.day(t.deadline))throw Error('任务截止早于开始：'+t.name);if(t.status&&!C.STATUSES.includes(t.status))throw Error('任务状态不受支持：'+t.status);if(t.progress!==undefined&&t.progress!==''&&(!Number.isFinite(Number(t.progress))||Number(t.progress)<0||Number(t.progress)>100))throw Error('任务进度必须为 0–100');if(t.dependencies&&!Array.isArray(t.dependencies))throw Error('依赖关系应为数组。');if(t.history){if(!Array.isArray(t.history)||!t.history.length)throw Error('事件记录为空或格式错误');t.history.forEach(e=>{if(!C.validDate(e.date)||!e.snapshot||typeof e.snapshot.name!=='string'||!C.STATUSES.includes(e.snapshot.status)||!Number.isFinite(Number(e.snapshot.progress))||Number(e.snapshot.progress)<0||Number(e.snapshot.progress)>100)throw Error('历史事件字段不完整');validateTask({...e.snapshot,history:undefined});});}}
function parseImport(text,filename){let input;if(filename.toLowerCase().endsWith('.csv')){input=C.parseCSV(text).map(row=>{const fields={'所属项目':'projectName','子项目/阶段':'phaseName','子项目负责人':'phaseOwner','任务名称':'name','负责人':'owner','截止日期':'deadline','当前状态':'status','任务优先级':'priority','完成时间':'completedAt','备注说明':'note'};const task={...row};Object.entries(fields).forEach(([cn,key])=>{if(row[cn]!==undefined)task[key]=row[cn];});if(Object.values(C.PRIORITIES).includes(task.priority))task.priority=Object.keys(C.PRIORITIES).find(k=>C.PRIORITIES[k]===task.priority);if(task.dependencies){try{task.dependencies=JSON.parse(task.dependencies);}catch(e){throw Error('CSV 依赖字段无效');}}task.blocked=task.blocked==='true';return task;});}else input=JSON.parse(text);const tasks=Array.isArray(input)?input:input.tasks;if(!Array.isArray(tasks)||tasks.length>10000)throw Error('请选择含 0–10000 条任务的 JSON 或 CSV。');const ids=new Set();const normalized=tasks.map(t=>{validateTask(t);const n=C.normalize(t);if(ids.has(n.id))throw Error('导入文件包含重复任务 ID');ids.add(n.id);return n;});const projects=Array.isArray(input.projects)?input.projects:[],risks=Array.isArray(input.risks)?input.risks:[];projects.forEach(p=>{if(!p||typeof p.id!=='string'||typeof p.name!=='string'||typeof p.color!=='string'||!/^#[a-f0-9]{6}$/i.test(p.color)||!Array.isArray(p.milestones)||!Array.isArray(p.phases))throw Error('项目元数据格式不正确');p.milestones.forEach(x=>{if(!Array.isArray(x)||typeof x[0]!=='string'||!C.validDate(x[1])||!Array.isArray(x[2])||!x[2].length)throw Error('里程碑格式不正确');});});risks.forEach(r=>{if(!r||typeof r.id!=='string'||typeof r.taskId!=='string'||!Array.isArray(r.history)||r.history.some(e=>!C.validDate(e.date)||!['待处理','处理中','已关闭'].includes(e.status)||typeof e.note!=='string'))throw Error('风险记录格式不正确');});return {tasks:normalized,projects,risks,full:!Array.isArray(input)&&input.format==='project-board-v2'};}
let pendingImport=null;
async function prepareImport(file){if(!file||!canEdit())return;try{if(file.size>10*1024*1024)throw Error('文件请小于 10 MB');const data=parseImport(await file.text(),file.name),ds=dataset(),existingIds=new Set(ds.tasks.map(t=>t.id));const fresh=data.tasks.filter(t=>!existingIds.has(t.id)),duplicate=data.tasks.length-fresh.length;const all=[...ds.tasks,...fresh],ids=new Set(all.map(t=>t.id));if(fresh.some(t=>t.dependencies.some(dep=>!ids.has(dep))))throw Error('导入任务含不存在的前置任务，请使用完整 JSON 备份。');const graph=new Map(all.map(t=>[t.id,t.dependencies]));const visited=new Set(),stack=new Set();function visit(id){if(stack.has(id))throw Error('导入任务存在循环依赖');if(visited.has(id))return;stack.add(id);(graph.get(id)||[]).forEach(visit);stack.delete(id);visited.add(id);}all.forEach(t=>visit(t.id));const projects=data.projects.filter(p=>!ds.projects.some(k=>k.id===p.id)),risks=data.risks.filter(r=>!ds.risks.some(k=>k.id===r.id)&&ids.has(r.taskId));pendingImport={merged:{...ds,tasks:all,projects:[...ds.projects,...projects],risks:[...ds.risks,...risks]},restored:data.full?{version:2,tasks:data.tasks,projects:data.projects,risks:data.risks}:null};modal('确认合并导入',`<div class="modal-body"><p>文件：${esc(file.name)}</p><p class="detail-record">新增 ${fresh.length} 条任务，跳过 ${duplicate} 条已有 ID，新增 ${projects.length} 个项目及 ${risks.length} 条风险记录。<br>目标：体验项目。现有同 ID 记录保留，不会被文件覆盖。</p><label class="form-field" style="margin:15px 0">导入方式<select id="importStrategy"><option value="merge">合并新增，保留现有相同 ID</option>${data.full?'<option value="replace">从完整备份恢复，替换体验项目全部数据</option>':''}</select></label><p class="field-hint">CSV 仅包含任务快照。完整 JSON 可恢复历史；选择替换将清除体验项目现有修改，请先备份。恢复后不会重新导入初始项目。</p></div>`,action('close-modal','取消')+action('confirm-import','合并导入','','button primary'));}catch(e){toast('导入失败：'+e.message);}finally{$('#importFile').value='';}}
function confirmImport(){if(!pendingImport)return;const ds=$('#importStrategy')?.value==='replace'?pendingImport.restored:pendingImport.merged;if(!ds)throw Error('当前文件不支持完整恢复');saveDataset({...dataset(),...ds,version:4});pendingImport=null;closeModal();resetFilters();reportText='';render();toast('导入已完成，重复 ID 已跳过');}
function setDate(date){if(!C.validDate(date)){toast('请选择有效日期');context();return;}state.date=date;reportText='';render();}
function newProject(){projectEditor();}
function projectEditor(id){if(!canEdit())return;const p=dataset().projects.find(p=>p.id===id)||{name:'',owner:'',category:'项目',start:cutoff(),end:'',goal:''};modal(id?'编辑项目':'创建项目',`<form id="projectForm" data-id="${esc(id||'')}" class="modal-body"><div class="form-grid">${formField('项目名称 *','name','text',p.name,'required maxlength="100"',true)}${formField('项目负责人 / 角色 *','owner','text',p.owner,'required maxlength="40"')}${formField('业务类别','category','text',p.category,'maxlength="60"')}${formField('开始日期','start','date',p.start)}${formField('结束日期','end','date',p.end)}<label class="form-field full">项目目标<textarea name="goal" maxlength="2000">${esc(p.goal)}</textarea></label></div><p id="formError" class="form-error" role="alert"></p><div class="modal-footer">${action('close-modal','取消')}<button class="button primary" type="submit">${id?'保存项目':'创建项目'}</button></div></form>`);}
function commitProject(form){const f=new FormData(form),id=form.dataset.id,ds=dataset(),old=ds.projects.find(p=>p.id===id);const name=String(f.get('name')).trim(),owner=String(f.get('owner')).trim(),start=f.get('start'),end=f.get('end');if(!name||!owner)throw Error('请填写项目名称和负责人');if(ds.projects.some(p=>p.id!==id&&p.name===name))throw Error('已有同名项目，请使用不同名称');if(start&&end&&start>end)throw Error('结束日期不能早于开始日期');const p={...old,id:id||'project-'+C.uid(),name,short:name,owner,category:String(f.get('category')),start,end,color:old?.color||'#4e73e8',icon:'folder',goal:String(f.get('goal')),description:String(f.get('goal'))||'项目已创建，可以开始任务拆解。',phases:old?.phases||[],milestones:old?.milestones||[],createdAt:old?.createdAt||cutoff()};const tasks=ds.tasks.map(t=>t.projectId===p.id?{...t,projectName:name,history:t.history?.map(e=>({...e,snapshot:{...e.snapshot,projectName:name}}))}:t);saveDataset({...ds,tasks,projects:old?ds.projects.map(x=>x.id===id?p:x):[...ds.projects,p]});closeModal();navigate('projects');state.detail=p.id;reportText='';render();toast(old?'项目已更新':'项目已创建，可新增阶段和任务');}
function deleteProject(id){if(!canEdit())return;const p=dataset().projects.find(p=>p.id===id);if(!p)return;modal('删除项目',`<div class="modal-body"><p>确认删除「${esc(p.name)}」及其全部任务、里程碑和风险记录？</p><p>此操作不能直接撤销，建议先到数据与设置导出 JSON 备份。</p></div>`,action('close-modal','取消')+action('confirm-delete-project','确认删除项目',`data-id="${esc(id)}"`,'button danger'));}
function confirmDeleteProject(id){const ds=dataset(),removed=new Set(ds.tasks.filter(t=>t.projectId===id).map(t=>t.id));const tasks=ds.tasks.filter(t=>t.projectId!==id).map(t=>({...t,dependencies:t.dependencies.filter(d=>!removed.has(d)),history:t.history?.map(e=>({...e,snapshot:{...e.snapshot,dependencies:(e.snapshot.dependencies||[]).filter(d=>!removed.has(d))}}))}));saveDataset({...ds,projects:ds.projects.filter(p=>p.id!==id),tasks,risks:ds.risks.filter(r=>!removed.has(r.taskId))});closeModal();state.detail=null;reportText='';resetFilters();render();toast('项目及关联记录已删除');}
function phaseEditor(id){if(!canEdit())return;modal('新增项目阶段',`<form id="phaseForm" data-id="${esc(id)}" class="modal-body">${formField('阶段名称 *','name','text','','required maxlength="60"')}<p class="field-hint">新增任务时可在所属阶段中选择或填写此名称。</p><p id="formError" class="form-error" role="alert"></p><div class="modal-footer">${action('close-modal','取消')}<button type="submit" class="button primary">保存阶段</button></div></form>`);}
function commitPhase(form){const name=String(new FormData(form).get('name')).trim(),ds=dataset(),p=ds.projects.find(p=>p.id===form.dataset.id);if(!name||!p)throw Error('请填写有效阶段名称');if(p.phases.includes(name))throw Error('该阶段已存在');saveDataset({...ds,projects:ds.projects.map(x=>x.id===p.id?{...x,phases:[...x.phases,name]}:x)});closeModal();render();toast('阶段已创建');}
function milestoneEditor(id){if(!canEdit())return;const p=model().projects.find(p=>p.id===id);if(!p)return;if(!p.tasks.length){toast('请先新增任务，再创建关联任务的里程碑');return;}modal('新增里程碑',`<form id="milestoneForm" data-id="${esc(id)}" class="modal-body"><div class="form-grid">${formField('里程碑名称 *','name','text','','required maxlength="100"',true)}${formField('计划交付日期 *','date','date',cutoff(),'required')}</div><p>关联任务（至少选择一条）</p><div class="choice-list">${p.tasks.map(t=>`<label><input type="checkbox" name="tasks" value="${esc(t.id)}">${esc(t.name)}</label>`).join('')}</div><p id="formError" class="form-error" role="alert"></p><div class="modal-footer">${action('close-modal','取消')}<button type="submit" class="button primary">保存里程碑</button></div></form>`);}
function commitMilestone(form){const f=new FormData(form),name=String(f.get('name')).trim(),date=f.get('date'),ids=f.getAll('tasks'),ds=dataset(),p=ds.projects.find(p=>p.id===form.dataset.id);if(!p||!name||!C.validDate(date)||!ids.length)throw Error('请填写名称、有效日期并至少关联一条任务');saveDataset({...ds,projects:ds.projects.map(x=>x.id===p.id?{...x,milestones:[...x.milestones,[name,date,ids]]}:x)});closeModal();render();toast('里程碑已创建');}
function newRisk(){if(!canEdit())return;const tasks=model().tasks;if(!tasks.length){toast('请先创建任务，再记录风险');return;}modal('记录任务风险',`<form id="newRiskForm" class="modal-body"><label class="form-field">关联任务 *<select name="taskId" required>${tasks.map(t=>`<option value="${esc(t.id)}">${esc(t.projectName)} · ${esc(t.name)}</option>`).join('')}</select></label>${formField('风险名称 *','title','text','','required maxlength="100"')}${formField('风险负责人 / 角色 *','owner','text','','required maxlength="40"')}<label class="form-field">风险原因 *<textarea name="cause" required maxlength="2000"></textarea></label><label class="form-field">影响范围<textarea name="impact" maxlength="2000"></textarea></label><label class="form-field">处理建议<textarea name="action" maxlength="2000"></textarea></label><p id="formError" class="form-error" role="alert"></p><div class="modal-footer">${action('close-modal','取消')}<button type="submit" class="button primary">保存风险</button></div></form>`);}
function commitNewRisk(form){const f=new FormData(form),taskId=f.get('taskId'),title=String(f.get('title')).trim(),cause=String(f.get('cause')).trim(),owner=String(f.get('owner')).trim();if(!title||!cause||!owner||!model().tasks.some(t=>t.id===taskId))throw Error('请填写任务、风险名称、原因和负责人');const ds=dataset(),r={id:'risk-'+C.uid(),taskId,title,cause,owner,impact:String(f.get('impact')),action:String(f.get('action')),history:[{date:cutoff(),status:'待处理',note:cause}]};saveDataset({...ds,risks:[...ds.risks,r]});closeModal();reportText='';render();toast('风险已记录');}
function clearData(){modal('清空我的体验数据',`<div class="modal-body"><p>确认清空当前浏览器中此公开体验版的所有项目、任务、里程碑、风险和历史记录？</p><p>清空后恢复初始空白。此操作不可撤销；建议先导出 JSON 备份。其他应用的本地数据不受影响。</p></div>`,action('close-modal','取消')+action('confirm-clear-data','确认清空体验数据','','button danger'));}
function confirmClearData(){const next=window.BoardStorage.empty();write(KEYS.unified,next);unified=next;corruptKeys=new Set();memoryOnly=false;state.date=C.today();state.progressProject='all';state.riskScope='all';reportText='';pendingImport=null;resetFilters();closeModal();navigate('overview');toast('体验数据已清空，欢迎重新开始');}
function help(){modal('操作说明',`<div class="modal-body"><ol class="help-steps"><li>创建项目，填写目标、负责人或负责角色，并添加项目阶段。</li><li>新增任务，设置负责人、优先级和起止日期；在任务列表或看板更新状态。</li><li>在项目详情添加关联任务的里程碑，在进度页面查看甘特图和交付状态。</li><li>风险页面会提示逾期、临近截止与阻塞任务，也可主动记录风险并跟进处理状态。</li><li>数据分析会根据实际任务记录计算完成率，可生成周报、导出 JSON 或 CSV。</li><li>数据仅保存在当前浏览器，不上传任务信息，不同设备不自动同步。数据与设置中可确认清空体验数据。</li></ol></div>`,action('close-modal','关闭'));}

const actions={
'manage-projects':()=>{state.detail=null;resetFilters();navigate('projects');},'sidebar':()=>$('#sidebar').classList.toggle('open'),'help':help,'new-task':()=>taskEditor(),
'edit-task':el=>taskEditor(el.dataset.id),'delete-task':el=>deleteTask(el.dataset.id),'confirm-delete':el=>confirmDelete(el.dataset.id),'close-modal':closeModal,
'back-projects':()=>{state.detail=null;render();},'project-tasks':el=>{navigate('tasks');resetFilters();state.project=el.dataset.id;render();},'project-progress':el=>{navigate('progress');state.progressProject=el.dataset.id;render();},
'clear-filters':()=>{resetFilters();render();},'risk-update':el=>riskEditor(el.dataset.id),'generate-report':()=>report(false),'weekly-report':()=>report(true),'copy-report':copyReport,
'export-json':exportJSON,'export-csv':()=>exportCSV(false),'export-all-csv':()=>exportCSV(true),'raw-storage':rawStorage,'import':()=>{if(canEdit())$('#importFile').click();},'confirm-import':confirmImport,
'new-project':newProject,'edit-project':el=>projectEditor(el.dataset.id),'delete-project':el=>deleteProject(el.dataset.id),'confirm-delete-project':el=>confirmDeleteProject(el.dataset.id),'new-phase':el=>phaseEditor(el.dataset.id),'new-milestone':el=>milestoneEditor(el.dataset.id),'new-risk':newRisk,'clear-data':clearData,'confirm-clear-data':confirmClearData,'today':()=>setDate(C.today())
};
document.addEventListener('click',e=>{try{const el=e.target.closest('[data-action],[data-nav],[data-project],[data-task],[data-view],[data-milestone],[data-risk-scope]');if(!el)return;if(el.dataset.action){const result=actions[el.dataset.action]?.(el);if(result?.catch)result.catch(e=>toast(e.message));}else if(el.dataset.nav)navigate(el.dataset.nav);else if(el.dataset.project){if($('#modal').open)closeModal();navigate('projects');state.detail=el.dataset.project;render();}else if(el.dataset.task)taskDetail(el.dataset.task);else if(el.dataset.view){state.view=el.dataset.view;render();}else if(el.dataset.milestone)milestoneDetail(el.dataset.milestone);else if(el.dataset.riskScope){state.riskScope=el.dataset.riskScope;render();}}catch(error){toast(error.message);}});
document.addEventListener('change',e=>{const el=e.target;try{if(el.id==='asOf'){if(el.value==='custom'){$('#customDate').hidden=false;$('#customDate').focus();}else setDate(el.value);}else if(el.id==='customDate')setDate(el.value);else if(el.dataset.filter){state[el.dataset.filter]=el.value;render();}else if(el.dataset.statusId)setTaskStatus(el.dataset.statusId,el.value);else if(el.id==='progressProject'){state.progressProject=el.value;render();}else if(el.id==='importFile')prepareImport(el.files[0]);}catch(error){toast(error.message);render();}});
document.addEventListener('compositionstart',()=>isComposing=true);
document.addEventListener('compositionend',e=>{isComposing=false;if(e.target.id==='taskSearch')e.target.dispatchEvent(new Event('input',{bubbles:true}));});
document.addEventListener('input',e=>{if(e.target.id==='taskSearch'&&!isComposing&&!e.isComposing){const value=e.target.value,position=e.target.selectionStart;state.query=value;render();const next=$('#taskSearch');next.focus();if(['text','search'].includes(next.type))next.setSelectionRange(position,position);}if(e.target.id==='reportText')reportText=e.target.value;});
document.addEventListener('submit',e=>{if(!['taskForm','riskForm','projectForm','phaseForm','milestoneForm','newRiskForm'].includes(e.target.id))return;e.preventDefault();try{if(!canEdit())return;if(e.target.id==='taskForm')commitTask(e.target);else if(e.target.id==='riskForm')commitRisk(e.target);else if(e.target.id==='projectForm')commitProject(e.target);else if(e.target.id==='phaseForm')commitPhase(e.target);else if(e.target.id==='milestoneForm')commitMilestone(e.target);else commitNewRisk(e.target);}catch(error){const el=$('#formError');if(el)el.textContent=error.message;else toast(error.message);}});
document.addEventListener('dragstart',e=>{const el=e.target.closest('[data-drag-id]');if(!el||readonly())return;e.dataTransfer.setData('text/plain',el.dataset.dragId);e.dataTransfer.effectAllowed='move';});
document.addEventListener('dragover',e=>{const el=e.target.closest('[data-drop-status]');if(el&&!readonly()){e.preventDefault();el.classList.add('drag-over');}});
document.addEventListener('dragleave',e=>e.target.closest('[data-drop-status]')?.classList.remove('drag-over'));
document.addEventListener('drop',e=>{const el=e.target.closest('[data-drop-status]');if(!el)return;e.preventDefault();el.classList.remove('drag-over');try{setTaskStatus(e.dataTransfer.getData('text/plain'),el.dataset.dropStatus);}catch(error){toast(error.message);}});
window.addEventListener('hashchange',()=>{const page=location.hash.slice(1);if(nav.some(n=>n[0]===page)&&page!==state.page){state.page=page;state.detail=null;render();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#sidebar').classList.remove('open');});
window.addEventListener('storage',e=>{if(Object.values(KEYS).includes(e.key))toast('其他标签页更新了本地数据，请刷新当前页面后继续编辑。');});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
render();
})();
